-- Conectar con Percha publicaciones visibles de la web que no se conectaban solas (código/SKU equivocado en la web).
-- Solo pares seguros: mismo modelo (mismo nombre) y una sola variante posible. Packs y combos quedan para conectar a mano.
-- Con el control de sql/117: si el stock no coincide, queda «a decidir» y no se manda nada a la web.
update canal_items ci set variante_id = x.v, cruce = 'manual', actualizado = now()
  from (values (2841,'38359e32-09d5-43fc-ad7b-8a64ec170cf5'::uuid),(2065,'e665af38-c097-4e7f-882b-40069919f140'::uuid),(2066,'53329357-3467-4f5b-a52f-2377266a320e'::uuid),(2067,'0b8d81de-4955-45c5-a232-a4fc773cce6d'::uuid),(2064,'ba31fb5b-8c76-4c72-ad03-6e3af9726804'::uuid),(1614,'0bd94488-c627-4ed6-b7c2-98b7eba66bf1'::uuid),(1615,'6a4bf42d-a57d-4940-bd78-165914befdf8'::uuid),(1613,'5f673b8c-cbd5-40dd-909e-a3bd487c08db'::uuid),(1767,'b778f7a6-3ba0-40f5-9167-78054b151378'::uuid),(1766,'9d42c10b-c06f-4481-b3fa-3cd6763d2d19'::uuid),(1264,'31d71a8d-8b3c-4fdd-a9a8-ac8dcf677490'::uuid),(3615,'ad3c2ed1-b797-4d29-bb88-3cc290d98b6a'::uuid),(3616,'f9488380-c2cc-4627-95d1-0e69b5f4cf6e'::uuid),(3614,'8ffc4b41-0c2c-48cb-a77a-4ee224332b50'::uuid),(1933,'aedc1f2a-44d1-454c-a422-944efe43a6ca'::uuid),(1934,'d9444512-97c4-40d9-a21d-909ec9d1da99'::uuid),(1935,'6698d1a2-7b19-4c85-a9b7-f919dd741eed'::uuid),(1936,'6734cffa-bbaf-4bb5-ab68-3d2cdb20c49a'::uuid),(1937,'17d7db6a-6046-4d55-a638-d74ebd4e7c3d'::uuid),(1938,'0b955d56-d546-4e62-8a8c-a23f99ab470a'::uuid),(1981,'429bd835-698d-464e-8840-6c09d7528e45'::uuid),(1982,'c5bbeebd-ef40-4333-88bd-d3ae1f5d834e'::uuid),(3967,'5886e0f2-5e21-4d48-b852-fb8abb176d8f'::uuid),(3968,'f89e9fb6-0766-490b-87d6-7f524e34b57c'::uuid),(3969,'3abe2a8f-bdcd-4342-8b45-1fde378ef97d'::uuid)) as x(id, v) where ci.id = x.id and ci.variante_id is null;
select (select count(*) from canal_items where conexion_id='6ecb8eee-1108-463b-a6e4-8161815c730c' and publicado and variante_id is null) quedan_sin_conectar, (select count(*) from canal_items where stock_a_decidir) a_decidir;
